//! Barrage flatbuffers messages (`io.deephaven.barrage.flatbuf`), which travel in the
//! `app_metadata` of Arrow Flight messages.
//!
//! The types are generated by `flatc` from `proto/barrage/Barrage.fbs`. The schema declares no
//! `root_type`, so there are no `root_as_*` helpers; read a buffer with
//! [`flatbuffers::root`], which verifies it first:
//!
//! ```
//! use flatbuffers::FlatBufferBuilder;
//! use oxhaven_proto::barrage::{
//!     BarrageMessageType, BarrageMessageWrapper, BarrageMessageWrapperArgs, MAGIC,
//! };
//!
//! let mut builder = FlatBufferBuilder::new();
//! let wrapper = BarrageMessageWrapper::create(
//!     &mut builder,
//!     &BarrageMessageWrapperArgs {
//!         magic: MAGIC,
//!         msg_type: BarrageMessageType::None,
//!         msg_payload: None,
//!     },
//! );
//! builder.finish(wrapper, None);
//!
//! let read = flatbuffers::root::<BarrageMessageWrapper>(builder.finished_data()).unwrap();
//! assert_eq!(read.magic(), MAGIC);
//! ```

pub use crate::barrage_generated::io::deephaven::barrage::flatbuf::*;

/// The value of `BarrageMessageWrapper.magic` that marks `app_metadata` as a Barrage message:
/// ASCII `"dphn"` read as a little-endian integer.
///
/// Port of the constant `io.deephaven.extensions.barrage.util.BarrageUtil#FLATBUFFER_MAGIC`. The
/// same value is stated in the schema's comment on the `magic` field.
pub const MAGIC: u32 = 0x6E68_7064;
